package com.project7.localmanager;
import android.content.*;import android.content.res.*;import java.io.*;import java.nio.file.*;import java.util.*;
/** Deterministic two-connection checkpoint interleaving through actual Store transactions. */
public final class TrialAtomicWeekHost {
 public static void main(String[]args)throws Exception{File assets=new File(args[0]);Context c=new Context(assets,new AssetManager(assets));CoreDrawPolicy.prepare(c);HistoryDrawPolicy.prepare(c);SelectorPolicy.prepare(c);OfflineMechanismGateway.prepare(c);StoryMissionBridge.prepare(c);TrialRetryGateway.prepare(c);
  try(TrialRetryHost.Fixture b=new TrialRetryHost.Fixture(assets,7144)){
   byte[]raw=b.d.read(),inv=TrialRetryHost.doc(raw,"inv");List<byte[]>items=new ArrayList<>(LocalResourceEngine.array(TrialRetryHost.doc(inv,"items")));items.add(BsonLite.document("i",345,"w",1,"u",new BsonLite.UuidValue(LocalResourceEngine.uuid())));Files.write(b.d.file,BsonLite.withProfileDocument(raw,"inv",BsonLite.withProfileArray(inv,"items",items)));
   // A has distinct original Progress/Engine, sharing only the original account Store.
   LocalTutorialStore.Progress a=b.d.tutorials.load(StoryMissionStoreHost.ACCOUNT);LocalEventEngine ae=new LocalEventEngine((LocalEventCatalog)DreamAccess.get(b.d.engine,"catalog"),(LocalNewbeeCatalog)DreamAccess.get(b.d.engine,"newbeeCatalog"),a,0,b.d.read(),true);
   ByteArrayOutputStream checkpoint=new ByteArrayOutputStream();boolean pass=(Boolean)DreamAccess.stat(EventResetWeekGateway.class,"beforeWeek",new Class<?>[]{LocalGatewayServer.class,OutputStream.class,byte[].class,String.class,LocalTutorialStore.Progress.class,LocalEventEngine.class,String.class},b.d.g,checkpoint,TrialRetryHost.EID,StoryMissionStoreHost.ACCOUNT,a,ae,"handleResetWeekAsk");TrialRetryHost.check(pass&&BsonLite.documentValue(b.d.read(),"q7TrialRetryPending")==null,"A original beforeWeek checkpoint passes without pending");
   // B's real accepted third loss commits Profile+Progress then faults the receipt ACK.
   b.begin(315,14);b.finish(315,14,0);b.begin(315,14);b.finish(315,14,0);b.begin(315,14);android.system.Os.afterRename=name->{if(name.endsWith(StoryMissionStoreHost.ACCOUNT+".bson")){android.system.Os.afterRename=null;android.system.Os.failBefore=true;}};try{b.finish(315,14,0);throw new AssertionError("B terminal ACK fault");}catch(IOException expected){}
   byte[]pending=b.d.read();Properties before=a.toProperties();String scope=a.weekCommit;TrialRetryHost.check(BsonLite.documentValue(pending,"q7TrialRetryPending")!=null,"B durable real pending appears after A checkpoint");
   for(String method:new String[]{"handleIncWeekAsk","handleResetWeekAsk","requestEnterStory","requestEnterStoryByEnding","handleResetWeek"}){
    LocalResourceEngine.Result r=b.d.store.updateServices(StoryMissionStoreHost.ACCOUNT,method,BsonLite.document("i",1,"e",1267),a);
    TrialRetryHost.check(Arrays.equals(pending,r.profile)&&Arrays.equals(pending,b.d.read())&&before.equals(a.toProperties())&&scope.equals(a.weekCommit),"actual locked Store rejects stale-checkpoint scope mutation "+method);
    TrialRetryHost.check(r.replies.size()==1&&r.replies.get(0).method.equals("showMessageStr")&&BsonLite.stringValue(r.replies.get(0).parameters,"m").contains("试炼"),"specific lock-bound trial guard not unrelated busy reject "+method);
    // Exact original downstream callback function; checkpoint interleaving is not a socket scheduler.
    ByteArrayOutputStream callback=new ByteArrayOutputStream();StoryMissionStoreHost.call(b.d.g,"completeCallback",new Class<?>[]{OutputStream.class,byte[].class,int.class,String.class},callback,TrialRetryHost.EID,615,method);TrialRetryHost.reply(StoryMissionStoreHost.frames(callback.toByteArray()),"serverCallbackCarrier");
   }
   System.out.println("PASS two original connection states: beforeWeek passes -> B actual wire pending -> original Store.updateServices five scope methods retain exact profile/Progress/receipt; original downstream callback returns");
   // Non-scope Week methods are allowed through their original typed producers.
   for(String method:new String[]{"updateStoryClickFlag","requestChangeAVGLevel"}){LocalResourceEngine.Result r=b.d.store.updateServices(StoryMissionStoreHost.ACCOUNT,method,BsonLite.document("lv",1,"slv",1),a);if(method.equals("requestChangeAVGLevel"))TrialRetryHost.check(r.replies.stream().anyMatch(v->v.method.equals("replyChangeAVGLevel")),"pending does not swallow original AVG typed reply");for(LocalResourceEngine.Reply v:r.replies)if(v.method.equals("showMessageStr"))TrialRetryHost.check(!Objects.toString(BsonLite.stringValue(v.parameters,"m"),"").contains("恢复当前试炼"),"non-scope method not swallowed by pending guard");TrialRetryHost.check(BsonLite.documentValue(b.d.read(),"q7TrialRetryPending")!=null&&scope.equals(a.weekCommit),"non-scope method retains receipt/scope");}
   LocalTutorialStore.Progress loaded=b.d.tutorials.load(StoryMissionStoreHost.ACCOUNT);LocalEventEngine engine=new LocalEventEngine((LocalEventCatalog)DreamAccess.get(b.d.engine,"catalog"),(LocalNewbeeCatalog)DreamAccess.get(b.d.engine,"newbeeCatalog"),loaded,0,b.d.read(),true);TrialRetryGateway.recover(b.d.g,StoryMissionStoreHost.ACCOUNT,loaded,engine);
   ByteArrayOutputStream out=new ByteArrayOutputStream();TrialRetryHost.reliable(b,out,"handleResetWeekAsk",BsonLite.EMPTY_DOCUMENT,997,loaded,engine);List<ProtoLite.EntityMessage>frames=StoryMissionStoreHost.frames(out.toByteArray());TrialRetryHost.reply(frames,"handleResetWeekReply");TrialRetryHost.reply(frames,"serverCallbackCarrier");TrialRetryHost.check(!scope.equals(loaded.weekCommit)&&BsonLite.documentValue(b.d.read(),"q7TrialRetryPending")==null,"recovery then actual reliable accepted scope transition releases callback");String newScope=loaded.weekCommit;int seq=998;for(String method:new String[]{"updateStoryClickFlag","requestChangeAVGLevel"}){out.reset();TrialRetryHost.reliable(b,out,method,BsonLite.document("lv",1,"slv",1),seq++,loaded,engine);frames=StoryMissionStoreHost.frames(out.toByteArray());TrialRetryHost.reply(frames,"serverCallbackCarrier");if(method.equals("requestChangeAVGLevel"))TrialRetryHost.reply(frames,"replyChangeAVGLevel");TrialRetryHost.check(newScope.equals(loaded.weekCommit),"actual reliable non-scope update preserves scope");}System.out.println("PASS non-scope Week updates retain original typed/callback producer; recover then real reliable Week RPC accepts new scope + original callback");
  }
 }
}
